        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ENDORSEMENT_ENROLMENT_WINDOW_DAYS end) as ENDORSEMENT_ENROLMENT_WINDOW_DAYS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LOCK_IN_PERIOD end) as LOCK_IN_PERIOD,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CONTINUITY_GUIDELINE end) as CONTINUITY_GUIDELINE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBER_ADDITION_GUIDELINE end) as MEMBER_ADDITION_GUIDELINE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBER_DELETION_GUIDELINE end) as MEMBER_DELETION_GUIDELINE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CLAIMS_REVIEW_EXPERIENCE_REFUND_CLAUSE_TERMS end) as CLAIMS_REVIEW_EXPERIENCE_REFUND_CLAUSE_TERMS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CONCURRENT_INSURANCE_DETAILS end) as CONCURRENT_INSURANCE_DETAILS,
        max(case when SOURCE_RUN = 'opus_health_v2' then CRC_PERCENTAGE end) as CRC_PERCENTAGE,
        max(case when SOURCE_RUN = 'opus_health_v2' then CRC_CLAUSE_TEXT end) as CRC_CLAUSE_TEXT,
        max(case when SOURCE_RUN = 'opus_health_v2' then LONG_TERM_TERM_ALLOWED_INDICATOR end) as LONG_TERM_TERM_ALLOWED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then SHORT_PERIOD_TERM_ALLOWED_INDICATOR end) as SHORT_PERIOD_TERM_ALLOWED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then BACKDATED_ISSUANCE_ALLOWED_INDICATOR end) as BACKDATED_ISSUANCE_ALLOWED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then MAXIMUM_ADVANCE_ISSUANCE_DAYS end) as MAXIMUM_ADVANCE_ISSUANCE_DAYS,
        max(case when SOURCE_RUN = 'opus_health_v2' then INSTALMENT_IDENTIFIER_ALLOWED_INDICATOR end) as INSTALMENT_IDENTIFIER_ALLOWED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then PERMITTED_POLICY_PERIOD_YEARS end) as PERMITTED_POLICY_PERIOD_YEARS,
        max(case when SOURCE_RUN = 'opus_health_v2' then PERMITTED_POLICY_PERIOD_MONTHS end) as PERMITTED_POLICY_PERIOD_MONTHS,
        max(case when SOURCE_RUN = 'opus_health_v2' then PERMITTED_POLICY_PERIOD_DAYS end) as PERMITTED_POLICY_PERIOD_DAYS,
        max(case when SOURCE_RUN = 'opus_health_v2' then GENERIC_CANCELLATION_ALLOWED_INDICATOR end) as GENERIC_CANCELLATION_ALLOWED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then EXPIRED_POLICY_CANCELLATION_ALLOWED_INDICATOR end) as EXPIRED_POLICY_CANCELLATION_ALLOWED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then MAXIMUM_BACKDATED_ISSUANCE_DAYS end) as MAXIMUM_BACKDATED_ISSUANCE_DAYS,
        max(case when SOURCE_RUN = 'opus_health_delta3' then PRE_EXISTING_DISEASE_COVER_BASIS end) as PRE_EXISTING_DISEASE_COVER_BASIS,
        max(case when SOURCE_RUN = 'opus_health_delta3' then INITIAL_WAITING_PERIOD_ONE_YEAR end) as INITIAL_WAITING_PERIOD_ONE_YEAR,
        max(case when SOURCE_RUN = 'opus_health_delta3' then INITIAL_WAITING_PERIOD_THIRTY_DAY end) as INITIAL_WAITING_PERIOD_THIRTY_DAY,
        max(case when SOURCE_RUN = 'opus_health_delta3' then POLICY_EXCLUSIONS_DESCRIPTION end) as POLICY_EXCLUSIONS_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SPECIAL_PERILS_COVERED_DESCRIPTION end) as SPECIAL_PERILS_COVERED_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_delta3' then ATTACHED_CLAUSES_DESCRIPTION end) as ATTACHED_CLAUSES_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_delta3' then OTHER_CONDITIONS end) as OTHER_CONDITIONS,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when INCEPTION_ENROLMENT_WINDOW_DAYS is not null or ENDORSEMENT_ENROLMENT_WINDOW_DAYS is not null or LOCK_IN_PERIOD is not null or CONTINUITY_GUIDELINE is not null or MEMBER_ADDITION_GUIDELINE is not null or MEMBER_DELETION_GUIDELINE is not null or CLAIMS_REVIEW_EXPERIENCE_REFUND_CLAUSE_TERMS is not null or CONCURRENT_INSURANCE_DETAILS is not null or CRC_PERCENTAGE is not null or CRC_CLAUSE_TEXT is not null or LONG_TERM_TERM_ALLOWED_INDICATOR is not null or SHORT_PERIOD_TERM_ALLOWED_INDICATOR is not null or BACKDATED_ISSUANCE_ALLOWED_INDICATOR is not null or MAXIMUM_ADVANCE_ISSUANCE_DAYS is not null or INSTALMENT_IDENTIFIER_ALLOWED_INDICATOR is not null or PERMITTED_POLICY_PERIOD_YEARS is not null or PERMITTED_POLICY_PERIOD_MONTHS is not null or PERMITTED_POLICY_PERIOD_DAYS is not null or GENERIC_CANCELLATION_ALLOWED_INDICATOR is not null or EXPIRED_POLICY_CANCELLATION_ALLOWED_INDICATOR is not null or MAXIMUM_BACKDATED_ISSUANCE_DAYS is not null or PRE_EXISTING_DISEASE_COVER_BASIS is not null or INITIAL_WAITING_PERIOD_ONE_YEAR is not null or INITIAL_WAITING_PERIOD_THIRTY_DAY is not null or POLICY_EXCLUSIONS_DESCRIPTION is not null or SPECIAL_PERILS_COVERED_DESCRIPTION is not null or ATTACHED_CLAUSES_DESCRIPTION is not null or OTHER_CONDITIONS is not null
                     then md5(upper(coalesce(cast(INCEPTION_ENROLMENT_WINDOW_DAYS as varchar), '') || '|' || coalesce(cast(ENDORSEMENT_ENROLMENT_WINDOW_DAYS as varchar), '') || '|' || coalesce(cast(LOCK_IN_PERIOD as varchar), '') || '|' || coalesce(cast(CONTINUITY_GUIDELINE as varchar), '') || '|' || coalesce(cast(MEMBER_ADDITION_GUIDELINE as varchar), '') || '|' || coalesce(cast(MEMBER_DELETION_GUIDELINE as varchar), '') || '|' || coalesce(cast(CLAIMS_REVIEW_EXPERIENCE_REFUND_CLAUSE_TERMS as varchar), '') || '|' || coalesce(cast(CONCURRENT_INSURANCE_DETAILS as varchar), '') || '|' || coalesce(cast(CRC_PERCENTAGE as varchar), '') || '|' || coalesce(cast(CRC_CLAUSE_TEXT as varchar), '') || '|' || coalesce(cast(LONG_TERM_TERM_ALLOWED_INDICATOR as varchar), '') || '|' || coalesce(cast(SHORT_PERIOD_TERM_ALLOWED_INDICATOR as varchar), '') || '|' || coalesce(cast(BACKDATED_ISSUANCE_ALLOWED_INDICATOR as varchar), '') || '|' || coalesce(cast(MAXIMUM_ADVANCE_ISSUANCE_DAYS as varchar), '') || '|' || coalesce(cast(INSTALMENT_IDENTIFIER_ALLOWED_INDICATOR as varchar), '') || '|' || coalesce(cast(PERMITTED_POLICY_PERIOD_YEARS as varchar), '') || '|' || coalesce(cast(PERMITTED_POLICY_PERIOD_MONTHS as varchar), '') || '|' || coalesce(cast(PERMITTED_POLICY_PERIOD_DAYS as varchar), '') || '|' || coalesce(cast(GENERIC_CANCELLATION_ALLOWED_INDICATOR as varchar), '') || '|' || coalesce(cast(EXPIRED_POLICY_CANCELLATION_ALLOWED_INDICATOR as varchar), '') || '|' || coalesce(cast(MAXIMUM_BACKDATED_ISSUANCE_DAYS as varchar), '') || '|' || coalesce(cast(PRE_EXISTING_DISEASE_COVER_BASIS as varchar), '') || '|' || coalesce(cast(INITIAL_WAITING_PERIOD_ONE_YEAR as varchar), '') || '|' || coalesce(cast(INITIAL_WAITING_PERIOD_THIRTY_DAY as varchar), '') || '|' || coalesce(cast(POLICY_EXCLUSIONS_DESCRIPTION as varchar), '') || '|' || coalesce(cast(SPECIAL_PERILS_COVERED_DESCRIPTION as varchar), '') || '|' || coalesce(cast(ATTACHED_CLAUSES_DESCRIPTION as varchar), '') || '|' || coalesce(cast(OTHER_CONDITIONS as varchar), '')))
                end as SAT_POLICY_TERMS_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_TERMS_HASHDIFF is not null
